-- from 20260727131000_enterprise_phase2_part3b_remediation
CREATE OR REPLACE FUNCTION prevent_finalized_network_mutation()
RETURNS TRIGGER AS $$
DECLARE protected BOOLEAN := FALSE;
BEGIN
  protected := CASE TG_TABLE_NAME
    WHEN 'network_agreements' THEN OLD.status IN ('APPROVED','PENDING_EXECUTION','ACTIVE','EXPIRED','TERMINATED','SUPERSEDED')
    WHEN 'network_royalty_runs' THEN OLD.status IN ('FINALIZED','REVERSED')
    WHEN 'network_commission_runs' THEN OLD.status IN ('FINALIZED','REVERSED')
    WHEN 'network_claims' THEN OLD.status IN ('APPROVED','PARTIALLY_APPROVED','SETTLED')
    WHEN 'network_target_plans' THEN OLD.status IN ('APPROVED','FINALIZED','ACTIVE')
    WHEN 'network_training_assignments' THEN OLD.status IN ('COMPLETED','EXPIRED')
    WHEN 'network_compliance_records' THEN OLD.status IN ('COMPLIANT','NON_COMPLIANT','EXPIRED')
    ELSE FALSE
  END;
  IF protected THEN
    RAISE EXCEPTION 'Finalized Enterprise Business Network history is immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION enforce_network_parent_organization()
RETURNS TRIGGER AS $$
DECLARE parent_org TEXT;
BEGIN
  EXECUTE format('SELECT "organizationKey" FROM %I WHERE id = $1', TG_ARGV[0])
    INTO parent_org USING (to_jsonb(NEW) ->> TG_ARGV[1]);
  IF parent_org IS NULL OR parent_org <> NEW."organizationKey" THEN
    RAISE EXCEPTION 'Cross-organization Enterprise Business Network reference denied';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;


-- from 20260727132000_enterprise_phase2_part3b_agreement_supersession
CREATE OR REPLACE FUNCTION prevent_finalized_network_mutation()
RETURNS TRIGGER AS $$
DECLARE protected BOOLEAN := FALSE;
BEGIN
  protected := CASE TG_TABLE_NAME
    WHEN 'network_agreements' THEN OLD.status IN ('APPROVED','PENDING_EXECUTION','ACTIVE','EXPIRED','TERMINATED','SUPERSEDED')
    WHEN 'network_royalty_runs' THEN OLD.status IN ('FINALIZED','REVERSED')
    WHEN 'network_commission_runs' THEN OLD.status IN ('FINALIZED','REVERSED')
    WHEN 'network_claims' THEN OLD.status IN ('APPROVED','PARTIALLY_APPROVED','SETTLED')
    WHEN 'network_target_plans' THEN OLD.status IN ('APPROVED','FINALIZED','ACTIVE')
    WHEN 'network_training_assignments' THEN OLD.status IN ('COMPLETED','EXPIRED')
    WHEN 'network_compliance_records' THEN OLD.status IN ('COMPLIANT','NON_COMPLIANT','EXPIRED')
    ELSE FALSE
  END;
  IF TG_TABLE_NAME = 'network_agreements' AND TG_OP = 'UPDATE'
     AND OLD.status IN ('APPROVED','PENDING_EXECUTION','ACTIVE')
     AND NEW.status = 'SUPERSEDED'
     AND (to_jsonb(NEW) - 'status' - 'supersededById' - 'updatedAt') =
         (to_jsonb(OLD) - 'status' - 'supersededById' - 'updatedAt') THEN
    protected := FALSE;
  END IF;
  IF protected THEN
    RAISE EXCEPTION 'Finalized Enterprise Business Network history is immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$ LANGUAGE plpgsql;


-- from 20260727133000_enterprise_phase2_part3b_child_immutability
CREATE OR REPLACE FUNCTION prevent_network_evidence_mutation()
RETURNS TRIGGER AS $$
DECLARE parent_status TEXT;
BEGIN
  IF TG_TABLE_NAME = 'network_partner_order_sources' THEN
    RAISE EXCEPTION 'Enterprise Business Network source attribution is immutable';
  ELSIF TG_TABLE_NAME = 'network_royalty_lines' THEN
    SELECT status INTO parent_status FROM "network_royalty_runs" WHERE id = OLD."runId";
  ELSIF TG_TABLE_NAME = 'network_commission_lines' THEN
    SELECT status INTO parent_status FROM "network_commission_runs" WHERE id = OLD."runId";
  ELSIF TG_TABLE_NAME = 'network_target_lines' THEN
    SELECT status INTO parent_status FROM "network_target_plans" WHERE id = OLD."planId";
  END IF;
  IF parent_status IN ('FINALIZED','REVERSED','APPROVED','ACTIVE') THEN
    RAISE EXCEPTION 'Finalized Enterprise Business Network child evidence is immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$ LANGUAGE plpgsql;


-- from 20260727140000_enterprise_phase2_part3c_wave1_finance_foundation
CREATE OR REPLACE FUNCTION finance_assert_same_organization_parent() RETURNS trigger AS $$
DECLARE
  parent_org TEXT;
BEGIN
  IF NEW."parentId" IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_TABLE_NAME = 'finance_cost_centers' THEN
    SELECT "organizationKey" INTO parent_org FROM "finance_cost_centers" WHERE "id" = NEW."parentId";
  ELSIF TG_TABLE_NAME = 'finance_profit_centers' THEN
    SELECT "organizationKey" INTO parent_org FROM "finance_profit_centers" WHERE "id" = NEW."parentId";
  ELSIF TG_TABLE_NAME = 'finance_accounts' THEN
    SELECT "organizationKey" INTO parent_org FROM "finance_accounts" WHERE "id" = NEW."parentId";
  END IF;
  IF parent_org IS NOT NULL AND parent_org <> NEW."organizationKey" THEN
    RAISE EXCEPTION 'Cross-organization parent relationship is not permitted';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;


-- from 20260727150000_enterprise_phase2_part3c_stagea_accounting_core
CREATE OR REPLACE FUNCTION finance_assert_journal_line_organization() RETURNS trigger AS $$
DECLARE
  account_org TEXT;
  cc_org TEXT;
  pc_org TEXT;
BEGIN
  SELECT "organizationKey" INTO account_org FROM "finance_accounts" WHERE "id" = NEW."accountId";
  IF account_org IS NULL OR account_org <> NEW."organizationKey" THEN
    RAISE EXCEPTION 'Journal line account must belong to the same organization';
  END IF;
  IF NEW."costCenterId" IS NOT NULL THEN
    SELECT "organizationKey" INTO cc_org FROM "finance_cost_centers" WHERE "id" = NEW."costCenterId";
    IF cc_org IS NULL OR cc_org <> NEW."organizationKey" THEN
      RAISE EXCEPTION 'Journal line cost center must belong to the same organization';
    END IF;
  END IF;
  IF NEW."profitCenterId" IS NOT NULL THEN
    SELECT "organizationKey" INTO pc_org FROM "finance_profit_centers" WHERE "id" = NEW."profitCenterId";
    IF pc_org IS NULL OR pc_org <> NEW."organizationKey" THEN
      RAISE EXCEPTION 'Journal line profit center must belong to the same organization';
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION finance_assert_journal_reversal_organization() RETURNS trigger AS $$
DECLARE
  ref_org TEXT;
BEGIN
  IF NEW."reversalOfJournalId" IS NOT NULL THEN
    SELECT "organizationKey" INTO ref_org FROM "finance_journals" WHERE "id" = NEW."reversalOfJournalId";
    IF ref_org IS NULL OR ref_org <> NEW."organizationKey" THEN
      RAISE EXCEPTION 'A reversal must reference a journal in the same organization';
    END IF;
  END IF;
  IF NEW."correctionOfJournalId" IS NOT NULL THEN
    SELECT "organizationKey" INTO ref_org FROM "finance_journals" WHERE "id" = NEW."correctionOfJournalId";
    IF ref_org IS NULL OR ref_org <> NEW."organizationKey" THEN
      RAISE EXCEPTION 'A correction must reference a journal in the same organization';
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION finance_reject_posted_journal_mutation() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD."status" = 'POSTED' THEN
      RAISE EXCEPTION 'Posted financial journals cannot be deleted';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD."status" = 'POSTED' AND (
    NEW."status" IS DISTINCT FROM OLD."status" OR
    NEW."journalNumber" IS DISTINCT FROM OLD."journalNumber" OR
    NEW."journalType" IS DISTINCT FROM OLD."journalType" OR
    NEW."postingDate" IS DISTINCT FROM OLD."postingDate" OR
    NEW."documentDate" IS DISTINCT FROM OLD."documentDate" OR
    NEW."totalDebit" IS DISTINCT FROM OLD."totalDebit" OR
    NEW."totalCredit" IS DISTINCT FROM OLD."totalCredit" OR
    NEW."fiscalYearId" IS DISTINCT FROM OLD."fiscalYearId" OR
    NEW."fiscalPeriodId" IS DISTINCT FROM OLD."fiscalPeriodId" OR
    NEW."reversalOfJournalId" IS DISTINCT FROM OLD."reversalOfJournalId" OR
    NEW."correctionOfJournalId" IS DISTINCT FROM OLD."correctionOfJournalId" OR
    NEW."postedById" IS DISTINCT FROM OLD."postedById" OR
    NEW."postedAt" IS DISTINCT FROM OLD."postedAt" OR
    (OLD."reversedByJournalId" IS NOT NULL AND NEW."reversedByJournalId" IS DISTINCT FROM OLD."reversedByJournalId") OR
    (OLD."successorJournalId" IS NOT NULL AND NEW."successorJournalId" IS DISTINCT FROM OLD."successorJournalId")
  ) THEN
    RAISE EXCEPTION 'Posted financial journals are immutable, except recording a single reversal/successor back-reference';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION finance_reject_posted_journal_line_mutation() RETURNS trigger AS $$
DECLARE
  parent_status TEXT;
BEGIN
  SELECT "status" INTO parent_status FROM "finance_journals" WHERE "id" = COALESCE(NEW."journalId", OLD."journalId");
  IF parent_status = 'POSTED' THEN
    RAISE EXCEPTION 'Lines of a posted financial journal are immutable';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION finance_reject_ledger_mutation() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'General ledger entries are append-only and immutable';
END;
$$ LANGUAGE plpgsql;


-- from 20260727150100_enterprise_phase2_part3c_stagea_immutability_fix
CREATE OR REPLACE FUNCTION finance_reject_posted_journal_mutation() RETURNS trigger AS $$
DECLARE
  old_row jsonb;
  new_row jsonb;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD."status" = 'POSTED' THEN
      RAISE EXCEPTION 'Posted financial journals cannot be deleted';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD."status" = 'POSTED' THEN
    old_row := to_jsonb(OLD) - 'reversedByJournalId' - 'successorJournalId' - 'updatedAt' - 'version';
    new_row := to_jsonb(NEW) - 'reversedByJournalId' - 'successorJournalId' - 'updatedAt' - 'version';
    IF old_row IS DISTINCT FROM new_row THEN
      RAISE EXCEPTION 'Posted financial journals are immutable, except recording a single reversal/successor back-reference';
    END IF;
    IF OLD."reversedByJournalId" IS NOT NULL AND NEW."reversedByJournalId" IS DISTINCT FROM OLD."reversedByJournalId" THEN
      RAISE EXCEPTION 'A posted journal''s reversal reference cannot be changed once set';
    END IF;
    IF OLD."successorJournalId" IS NOT NULL AND NEW."successorJournalId" IS DISTINCT FROM OLD."successorJournalId" THEN
      RAISE EXCEPTION 'A posted journal''s successor reference cannot be changed once set';
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;


