  IF NEW."orderNumber" IS NULL OR NEW."orderNumber" = '' THEN
    NEW."orderNumber" := 'MUV-ORD-' || TO_CHAR(CURRENT_DATE,'YYYY') || '-' || LPAD(NEXTVAL('commerce_order_number_seq')::TEXT,6,'0');
  END IF;
  RETURN NEW;
END; $$ LANGUAGE plpgsql;

