-- ============================================================
-- 5. CHECK constraints (hand-written SQL; confirmed absent from Neon;
--    not idempotence-guardable via plain SQL -- Postgres has no
--    "ADD CONSTRAINT IF NOT EXISTS" -- consistent with the non-idempotent
--    convention already used by every other migration in this project)
-- ============================================================
-- from 20260727040000_opportunity_sales_execution_v1
ALTER TABLE "opportunity_stages"
  ADD CONSTRAINT "opportunity_stages_probability_check"
  CHECK ("probabilityDefault" BETWEEN 0 AND 100);
ALTER TABLE "opportunities"
  ADD CONSTRAINT "opportunities_probability_check" CHECK ("probability" BETWEEN 0 AND 100),
  ADD CONSTRAINT "opportunities_estimated_value_check" CHECK ("estimatedValue" >= 0);
ALTER TABLE "opportunity_attachments"
  ADD CONSTRAINT "opportunity_attachments_size_check" CHECK ("sizeBytes" >= 0);
-- from 20260727050000_quotation_pricing_engine_v1
ALTER TABLE "quotation_line_items"
  ADD CONSTRAINT "quotation_line_quantity_check" CHECK ("quantity" > 0),
  ADD CONSTRAINT "quotation_line_values_check" CHECK ("unitPrice" >= 0 AND "discountValue" >= 0 AND "subtotal" >= 0 AND "discountAmount" >= 0 AND "taxAmount" >= 0 AND "total" >= 0);
ALTER TABLE "quotation_versions"
  ADD CONSTRAINT "quotation_validity_check" CHECK ("validUntil" >= "issueDate"),
  ADD CONSTRAINT "quotation_totals_check" CHECK ("subtotal" >= 0 AND "discountTotal" >= 0 AND "taxTotal" >= 0 AND "grandTotal" >= 0);
-- from 20260727060000_commerce_operations_v2
ALTER TABLE "stock_ledger_entries" ADD CONSTRAINT "stock_ledger_quantity_nonzero" CHECK ("quantity" <> 0);
ALTER TABLE "inventory_reservations" ADD CONSTRAINT "reservation_quantity_positive" CHECK ("quantity" > 0);
ALTER TABLE "inventory_allocations" ADD CONSTRAINT "allocation_quantity_positive" CHECK ("quantity" > 0);
ALTER TABLE "inventory_damage_records" ADD CONSTRAINT "damage_quantity_positive" CHECK ("quantity" > 0);
ALTER TABLE "commerce_payments" ADD CONSTRAINT "commerce_payment_amount_positive" CHECK ("amount" > 0);
-- from 20260727070000_customer_growth_intelligence_v2
ALTER TABLE "customer_referrals" ADD CONSTRAINT "customer_referrals_no_self_referral" CHECK ("referrerCustomerId" <> "referredCustomerId");
-- from 20260727140000_enterprise_phase2_part3c_wave1_finance_foundation
ALTER TABLE "finance_cost_centers" ADD CONSTRAINT "finance_cost_centers_no_self_parent" CHECK ("parentId" IS NULL OR "parentId" <> "id");
ALTER TABLE "finance_profit_centers" ADD CONSTRAINT "finance_profit_centers_no_self_parent" CHECK ("parentId" IS NULL OR "parentId" <> "id");
ALTER TABLE "finance_accounts" ADD CONSTRAINT "finance_accounts_no_self_parent" CHECK ("parentId" IS NULL OR "parentId" <> "id");
ALTER TABLE "finance_fiscal_years" ADD CONSTRAINT "finance_fiscal_years_valid_range" CHECK ("endDate" > "startDate");
ALTER TABLE "finance_fiscal_periods" ADD CONSTRAINT "finance_fiscal_periods_valid_range" CHECK ("endDate" > "startDate");
-- from 20260727150000_enterprise_phase2_part3c_stagea_accounting_core
ALTER TABLE "finance_journal_lines" ADD CONSTRAINT "finance_journal_lines_valid_side" CHECK (
  ("debitAmount" > 0 AND "creditAmount" = 0) OR ("creditAmount" > 0 AND "debitAmount" = 0)
);
ALTER TABLE "finance_ledger_entries" ADD CONSTRAINT "finance_ledger_entries_valid_side" CHECK (
  ("debitAmount" > 0 AND "creditAmount" = 0) OR ("creditAmount" > 0 AND "debitAmount" = 0)
);
ALTER TABLE "finance_journals" ADD CONSTRAINT "finance_journals_no_self_reversal" CHECK ("reversalOfJournalId" IS NULL OR "reversalOfJournalId" <> "id");
ALTER TABLE "finance_journals" ADD CONSTRAINT "finance_journals_no_self_correction" CHECK ("correctionOfJournalId" IS NULL OR "correctionOfJournalId" <> "id");
-- from 20260727160000_enterprise_phase2_part3c_stageb_accounts_receivable
ALTER TABLE "finance_receivable_invoices" ADD CONSTRAINT "finance_receivable_invoices_totals_non_negative" CHECK ("subtotal" >= 0 AND "discountAmount" >= 0 AND "taxAmount" >= 0 AND "totalAmount" >= 0 AND "outstandingAmount" >= 0);
ALTER TABLE "finance_customer_receipts" ADD CONSTRAINT "finance_customer_receipts_amount_positive" CHECK ("amount" > 0 AND "unallocatedAmount" >= 0);
ALTER TABLE "finance_receipt_allocations" ADD CONSTRAINT "finance_receipt_allocations_amount_positive" CHECK ("allocatedAmount" > 0);
ALTER TABLE "finance_receipt_allocations" ADD CONSTRAINT "finance_receipt_allocations_no_self_reversal" CHECK ("reversalOfAllocationId" IS NULL OR "reversalOfAllocationId" <> "id");
-- from 20260727170000_enterprise_phase2_part3c_stageb_accounts_payable
ALTER TABLE "finance_vendor_bills" ADD CONSTRAINT "finance_vendor_bills_totals_non_negative" CHECK ("subtotal" >= 0 AND "taxAmount" >= 0 AND "totalAmount" >= 0 AND "outstandingAmount" >= 0);
ALTER TABLE "finance_vendor_payments" ADD CONSTRAINT "finance_vendor_payments_amount_positive" CHECK ("amount" > 0 AND "unallocatedAmount" >= 0);
ALTER TABLE "finance_vendor_payment_allocations" ADD CONSTRAINT "finance_vendor_payment_allocations_amount_positive" CHECK ("allocatedAmount" > 0);
ALTER TABLE "finance_vendor_payment_allocations" ADD CONSTRAINT "finance_vendor_payment_allocations_no_self_reversal" CHECK ("reversalOfAllocationId" IS NULL OR "reversalOfAllocationId" <> "id");
-- from 20260727180000_enterprise_phase2_part3c_stageb_expense_banking
ALTER TABLE "finance_expense_lines" ADD CONSTRAINT "finance_expense_lines_claimed_positive" CHECK ("claimedAmount" > 0);
ALTER TABLE "finance_expense_lines" ADD CONSTRAINT "finance_expense_lines_approved_not_exceeding_claimed" CHECK ("approvedAmount" IS NULL OR ("approvedAmount" >= 0 AND "approvedAmount" <= "claimedAmount"));
ALTER TABLE "finance_bank_statement_lines" ADD CONSTRAINT "finance_bank_statement_lines_valid_side" CHECK (
  ("debitAmount" > 0 AND "creditAmount" = 0) OR ("creditAmount" > 0 AND "debitAmount" = 0)
);
ALTER TABLE "finance_reconciliation_matches" ADD CONSTRAINT "finance_reconciliation_matches_no_self_reversal" CHECK ("reversalOfMatchId" IS NULL OR "reversalOfMatchId" <> "id");
ALTER TABLE "finance_reconciliation_matches" ADD CONSTRAINT "finance_reconciliation_matches_one_target" CHECK (
  ("ledgerEntryId" IS NOT NULL AND "adjustmentJournalId" IS NULL) OR ("ledgerEntryId" IS NULL AND "adjustmentJournalId" IS NOT NULL)
);
-- from 20260727120000_enterprise_phase2_part3a_foundations (originally inline in
-- CREATE TABLE "phase2_policy_versions" -- that table already exists in Neon, so this
-- CHECK constraint from its original definition was never separately applied)
ALTER TABLE "phase2_policy_versions" ADD CONSTRAINT "phase2_policy_versions_version_check" CHECK ("version" > 0);
